package plates.ui

import plates.core.timing.PlateAnimationController
import plates.core.timing.PlatePartCue
import plates.core.timing.PlatePartFrame
import plates.core.timing.PlatePartId
import plates.core.timing.PlatePartPhase
import plates.core.timing.plateCueProgress
import plates.render.Frames

/**
 * [H11] The animation driver: remembers when each part's cue arrived and turns (cue, elapsed) into frames
 * through the core timing model. Read at a frame time; the UI ticks it per animation frame.
 *
 * [observe] stamps every part of a plate each frame, so a cue's clock starts at the first frame after it arrives
 * whether or not its part is painted then: a flag under a hidden panel keeps its place in the stagger.
 */
class PartClock(private val animation: PlateAnimationController, private val now: () -> Double) {
    private val started = HashMap<PlatePartId, Pair<PlatePartCue, Double>>()

    private fun progress(id: PlatePartId, cue: PlatePartCue, at: Double, t: Double) =
        if (cue.instant || cue.phase == PlatePartPhase.settled) 1.0
        else plateCueProgress(animation.style.motionFor(id), cue.delayMs, t - at)

    private fun stamp(id: PlatePartId, t: Double): Pair<PlatePartCue, Double> {
        val cue = animation.cueOf(id).value
        return started[id]?.takeIf { it.first == cue } ?: (cue to t).also { started[id] = it }
    }

    /** Notes, at [t], any new cue of [ids]. */
    fun observe(ids: Iterable<PlatePartId>, t: Double = now()) = ids.forEach { stamp(it, t) }

    fun frames(t: Double = now()): Frames = { id ->
        val (cue, at) = stamp(id, t)
        PlatePartFrame(cue.phase, progress(id, cue, at, t), animation.style.motionFor(id))
    }

    /** True while some part seen so far is still moving at [t]. */
    fun runningAt(t: Double) = started.any { (id, s) -> progress(id, s.first, s.second, t) < 1 }

    val running: Boolean get() = runningAt(now())
}
